const AXIS_IDS=['representation','transfer','formal','dynamics','organization','explanation','validation','robustness'];
export function safeURL(value){try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:null;}catch{return null;}}
export const safeUrl=safeURL;
const known=value=>Number.isInteger(value)&&value>=0&&value<=4;
export function rankAxis(papers,axis){
  const rows=papers.filter(p=>p.role==='Buehler').map(p=>({paper:p,score:p.assessments?.[axis]?.score??null,rank:null}));
  rows.sort((a,b)=>(known(b.score)?b.score:-1)-(known(a.score)?a.score:-1)||String(a.paper.title).localeCompare(String(b.paper.title))||String(a.paper.id).localeCompare(String(b.paper.id)));
  let previous=null,rank=null;for(const [i,row] of rows.entries()){if(!known(row.score))continue;if(row.score!==previous)rank=i+1;row.rank=rank;previous=row.score;}return rows;
}
export function comparatorSummary(papers,axis){
  const values=papers.filter(p=>p.role==='Comparator').map(p=>p.assessments?.[axis]?.score).filter(known),scores=papers.filter(p=>p.role==='Buehler').map(p=>p.assessments?.[axis]?.score),low=values.length?Math.min(...values):null,high=values.length?Math.max(...values):null;
  return {low,high,comparatorN:values.length,buehlerN:scores.length,above:high===null?null:scores.filter(s=>known(s)&&s>high).length,within:high===null?null:scores.filter(s=>known(s)&&s>=low&&s<=high).length,below:low===null?null:scores.filter(s=>known(s)&&s<low).length,unknown:scores.filter(s=>!known(s)).length};
}
function averageRanks(values){const sorted=values.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v),ranks=Array(values.length);for(let i=0;i<sorted.length;){let j=i+1;while(j<sorted.length&&sorted[j].v===sorted[i].v)j++;const rank=(i+1+j)/2;for(let k=i;k<j;k++)ranks[sorted[k].i]=rank;i=j;}return ranks;}
export function rankCorrelation(papers,axisA,axisB){
  const pairs=papers.filter(p=>p.role==='Buehler').map(p=>[p.assessments?.[axisA]?.score,p.assessments?.[axisB]?.score]).filter(([a,b])=>known(a)&&known(b)),n=pairs.length;if(n<2)return {rho:null,n};
  const x=averageRanks(pairs.map(p=>p[0])),y=averageRanks(pairs.map(p=>p[1])),mx=x.reduce((a,b)=>a+b,0)/n,my=y.reduce((a,b)=>a+b,0)/n;let numerator=0,xx=0,yy=0;for(let i=0;i<n;i++){const dx=x[i]-mx,dy=y[i]-my;numerator+=dx*dy;xx+=dx*dx;yy+=dy*dy;}return {rho:xx===0||yy===0?null:Math.max(-1,Math.min(1,numerator/Math.sqrt(xx*yy))),n};
}
export function pairwiseCorrelations(papers,axes=AXIS_IDS){return axes.map(a=>axes.map(b=>({axisA:typeof a==='string'?a:a.id,axisB:typeof b==='string'?b:b.id,...rankCorrelation(papers,typeof a==='string'?a:a.id,typeof b==='string'?b:b.id)})));}
export function filterPapers(papers,{query='',family='all',role='Buehler'}={}){const terms=String(query).toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);return papers.filter(p=>(role==='all'||p.role===role)&&(family==='all'||p.family===family)&&terms.every(term=>JSON.stringify([p.title,p.shortTitle,p.authors,p.family,p.summary,p.surprise,p.detail,p.assessments]).toLocaleLowerCase().includes(term)));}
export function validateData(data){
  const fail=message=>{throw new Error(message);};if(!data||!Array.isArray(data.papers)||!data.papers.length||!Array.isArray(data.rubric?.axes))fail('No paper profiles or rubric were supplied.');
  const axes=new Set();for(const a of data.rubric.axes){if(!AXIS_IDS.includes(a.id)||axes.has(a.id)||!a.label||!a.question||!Array.isArray(a.anchors)||a.anchors.length!==5||a.anchors.some(s=>typeof s!=='string'))fail('The eight-axis rubric is invalid.');axes.add(a.id);}if(axes.size!==8)fail('All eight rubric axes are required.');
  const ids=new Set();for(const p of data.papers){if(!p.id||ids.has(p.id)||!p.title||!p.family||!['Buehler','Comparator'].includes(p.role)||!safeURL(p.url))fail('A paper has a missing or duplicate identity, title, role, family or safe primary source URL.');ids.add(p.id);
    if(!Array.isArray(p.authors)||!Array.isArray(p.coverage?.read)||!Array.isArray(p.coverage?.notRead)||!p.surprise||!p.detail)fail(`Paper ${p.id} lacks its reading record.`);
    for(const key of AXIS_IDS){const a=p.assessments?.[key];if(!a||!(a.score===null||known(a.score))||!['low','medium','high'].includes(a.confidence)||typeof a.rationale!=='string'||typeof a.locator!=='string')fail(`Paper ${p.id} has an invalid ${key} assessment.`);}
  }if(!data.papers.some(p=>p.role==='Buehler'))fail('The corpus has no Buehler papers.');return data;
}
const text=value=>Array.isArray(value)?value.join('; '):String(value??'');
function el(tag,value,className){const n=document.createElement(tag);if(value!==undefined)n.textContent=text(value);if(className)n.className=className;return n;}
function para(parent,label,value,className){const p=el('p',undefined,className);if(label)p.append(el('strong',label+' '));p.append(document.createTextNode(text(value)));parent.append(p);return p;}
function sourceLink(label,url){const n=el('a',label),safe=safeURL(url);if(safe){n.href=safe;n.target='_blank';n.rel='noopener noreferrer';}else{n.title='No valid source URL supplied';}return n;}
async function boot(){const $=id=>document.getElementById(id),status=$('b-status');try{
  const response=await fetch('./papers.json');if(!response.ok)throw new Error(`Profile download failed (HTTP ${response.status}).`);const data=validateData(await response.json()),axes=data.rubric.axes,buehler=data.papers.filter(p=>p.role==='Buehler'),comparators=data.papers.filter(p=>p.role==='Comparator'),rankings=Object.fromEntries(axes.map(a=>[a.id,rankAxis(data.papers,a.id)])),rankMaps=Object.fromEntries(axes.map(a=>[a.id,new Map(rankings[a.id].map(r=>[r.paper.id,r]))]));
  let selected=buehler.find(p=>p.id==='COPRESHEAF'||/copreshea/i.test(p.title))?.id||buehler[0].id,visible=buehler,listButtons=new Map(),matrixButtons=new Map();
  const option=(value,label)=>{const o=el('option',label);o.value=value;return o;};for(const a of axes)$('rank-axis').append(option(a.id,a.label+' · '+a.kind));$('rank-axis').value='representation';for(const family of [...new Set(buehler.map(p=>p.family))].sort())$('family-filter').append(option(family,family));
  function select(id,origin){selected=id;renderList();renderMatrix();renderDetail();(origin==='matrix'?matrixButtons:listButtons).get(id)?.focus();}
  function card(p,row,axis){const li=el('li'),button=el('button');button.type='button';button.setAttribute('aria-pressed',String(selected===p.id));const rating=p.assessments[axis],rank=el('span',p.role==='Comparator'?'Anchor':row.rank===null?'—':'#'+row.rank,'b-rank');rank.append(el('small',p.role==='Comparator'?'not ranked':row.rank===null?'unranked':'corpus rank'));const info=el('span');info.append(el('span',p.shortTitle||p.title,'b-title'),el('span',`${p.family} · ${p.year} · ${p.status}`,'b-meta'));if(p.readingLevel)info.append(el('span','Reading: '+p.readingLevel,'b-reading'));const category=el('span',rating.score===null?'?':rating.score+'/4','b-category');category.append(el('small',rating.confidence));button.setAttribute('aria-label',`${p.title}. ${p.role==='Comparator'?'Comparator; no rank':row.rank===null?'Unranked':'Corpus rank '+row.rank}. Category ${rating.score===null?'unknown':rating.score+' of 4'}, ${rating.confidence} confidence. Open evidence.`);button.append(rank,info,category);button.addEventListener('click',()=>select(p.id,'list'));li.append(button);listButtons.set(p.id,button);return li;}
  function renderList(){listButtons=new Map();const axis=$('rank-axis').value,target=$('ranked-papers'),ids=new Set(visible.map(p=>p.id));target.replaceChildren();for(const row of rankings[axis])if(ids.has(row.paper.id))target.append(card(row.paper,row,axis));if(!visible.length)target.append(el('li','No papers match. Change the search or family filter.','b-empty'));const comp=$('comparator-papers');comp.replaceChildren();for(const p of comparators)comp.append(card(p,null,axis));}
  function renderSummary(){const axis=axes.find(a=>a.id===$('rank-axis').value),target=$('axis-summary');target.replaceChildren(el('h3',axis.label),el('p',axis.question));para(target,'Dimension:',axis.kind);const s=comparatorSummary(data.papers,axis.id);$('benchmark-summary').textContent=s.comparatorN?`Named comparator range: ${s.low}–${s.high}/4 (${s.comparatorN} rated comparator papers). In the complete ${s.buehlerN}-paper Buehler corpus: ${s.above} above the highest comparator category, ${s.within} within the range, ${s.below} below, ${s.unknown} unknown. These are category comparisons with three named studies, not an estimate of the whole field.`:'No reviewed comparator rating is available on this axis; no benchmark comparison is calculated.';}
  function tableHead(target,comparison=false){target.replaceChildren();const row=el('tr'),first=el('th','Paper');first.scope='col';row.append(first);for(const axis of axes){const th=el('th',axis.short||axis.label);th.scope='col';th.append(el('small',axis.kind));row.append(th);}target.append(row);}
  function tableRows(target,papers,comparison=false){target.replaceChildren();for(const p of papers){const row=el('tr');row.dataset.selected=String(p.id===selected);const th=el('th');th.scope='row';const button=el('button',p.shortTitle||p.title);button.type='button';button.addEventListener('click',()=>select(p.id,'matrix'));th.append(button);if(p.readingLevel)th.append(el('small','Reading: '+p.readingLevel));row.append(th);matrixButtons.set(p.id,button);for(const a of axes){const r=p.assessments[a.id],rank=rankMaps[a.id].get(p.id)?.rank??null,cell=el('td'),value=el('span',undefined,'b-cell');value.style.setProperty('--cell-bg',r.score===null?'#eeeeea':['#f1eee6','#e9eee4','#dde8da','#ccdfcd','#b4d1bd'][r.score]);value.append(el('strong',comparison?(r.score===null?'?':r.score+'/4'):(rank===null?'unranked':'#'+rank)),el('small',(comparison?'':r.score===null?'? · ':r.score+'/4 · ')+r.confidence));cell.title=`${a.label}: ${r.score===null?'Unknown':r.score+'/4'}; ${r.confidence} confidence. ${r.rationale} Source: ${r.locator}`;value.setAttribute('aria-label',`${comparison?'Comparator, no rank':rank===null?'Unranked':'Corpus rank '+rank}. Category ${r.score===null?'unknown':r.score+' of 4'}, ${r.confidence} confidence.`);cell.append(value);row.append(cell);}target.append(row);}if(!papers.length){const row=el('tr'),cell=el('td','No matching papers. Reset the filters.');cell.colSpan=9;row.append(cell);target.append(row);}}
  function renderMatrix(){matrixButtons=new Map();tableHead($('matrix-head'));tableRows($('matrix-body'),rankings[$('rank-axis').value].map(r=>r.paper).filter(p=>visible.some(v=>v.id===p.id)));tableHead($('comparator-head'),true);tableRows($('comparator-body'),comparators,true);}
  function renderDetail(){const target=$('paper-detail');target.replaceChildren();const p=data.papers.find(p=>p.id===selected);if(!p){const h=el('h3','No paper selected');h.id='detail-title';target.append(h,el('p','Choose a paper to inspect its evidence.'));return;}target.append(el('p',`${p.role.toUpperCase()} / ${p.family}`,'eyebrow'));const title=el('h3',p.title);title.id='detail-title';target.append(title,el('p',p.authors),el('p',`${p.year} · ${p.status} · ${p.version||'Version not specified'}`));if(p.readingLevel)target.append(el('p','Reading coverage: '+p.readingLevel,'b-reading'));target.append(el('p',p.summary));const primary=el('p');primary.append(sourceLink('Read primary paper ↗',p.url));if(p.doi)primary.append(document.createTextNode(' · DOI '+p.doi));target.append(primary);
    const section=title=>{const s=el('section');s.append(el('h4',title));target.append(s);return s;};let s=section('The surprise—and its boundary');para(s,'Observation:',p.surprise.observation);para(s,'Interpretation:',p.surprise.interpretation);para(s,'Boundary:',p.surprise.boundary);para(s,'Source:',p.surprise.locator,'b-locator');s=section('A detail that changes the reading');para(s,'Detail:',p.detail.observation);para(s,'Consequence:',p.detail.consequence);para(s,'Source:',p.detail.locator,'b-locator');s=section('Eight separate judgments');for(const a of axes){const r=p.assessments[a.id],rank=rankMaps[a.id].get(p.id)?.rank;s.append(el('h5',`${a.label} · ${r.score===null?'unknown':r.score+'/4'} · ${r.confidence} confidence${p.role==='Buehler'&&rank?' · corpus #'+rank:''}`));para(s,'',r.rationale);for(const alternative of r.alternativeScores||[]){const dissent=el('div',undefined,'b-dissent');para(dissent,'Recorded dissent:',`${alternative.reviewer}: ${alternative.score===null?'unknown':alternative.score+'/4'} (not used in the displayed rank).`);para(dissent,'',alternative.rationale);s.append(dissent);}para(s,'Category:',r.score===null?'Insufficient reviewed evidence':a.anchors[r.score]);para(s,'Source:',r.locator,'b-locator');}s=section('Reading coverage');para(s,'Reviewed:',p.coverage.read.length?p.coverage.read:'No reviewed section specified');para(s,'Not reviewed:',p.coverage.notRead.length?p.coverage.notRead:'No additional omission specified; not an independent reproduction.');for(const ref of p.references||[]){if(!safeURL(ref.url))continue;const line=el('p');line.append(sourceLink(ref.title,ref.url));s.append(line);if(ref.scope)para(s,'Scope:',ref.scope);}}
  function renderFeature(){const target=$('copresheaves-feature'),p=buehler.find(p=>p.id==='COPRESHEAF'||/copreshea/i.test(p.title));if(!p){target.append(el('p','The copresheaves profile is not present in this snapshot.'));return;}target.append(el('h3',p.title));const a=el('div');para(a,'Observed contribution:',p.surprise.observation);para(a,'Why the representation matters:',p.assessments.representation.rationale);const b=el('div');para(b,'Interpretation:',p.surprise.interpretation);para(b,'Boundary:',p.surprise.boundary);target.append(a,b);const line=el('p',undefined,'b-locator');line.append(sourceLink('Primary source ↗',p.url),document.createTextNode(` · ${p.version||'Version unspecified'} · ${p.surprise.locator}`));target.append(line);}
  function renderCorrelation(){const head=$('correlation-head'),body=$('correlation-body'),row=el('tr');row.append(el('th','Axis'));for(const a of axes){const th=el('th',a.short||a.label);th.scope='col';row.append(th);}head.append(row);for(const [i,values] of pairwiseCorrelations(data.papers,axes).entries()){const tr=el('tr'),th=el('th',axes[i].short||axes[i].label);th.scope='row';tr.append(th);for(const value of values){const cell=el('td',value.rho===null?'undefined':value.rho.toFixed(2),'b-correlation');cell.append(el('small','n = '+value.n));cell.title=`${value.axisA} versus ${value.axisB}: ${value.rho===null?'undefined (constant axis or insufficient pairs)':value.rho.toFixed(4)}, pairwise n = ${value.n}. Descriptive rank correlation.`;tr.append(cell);}body.append(tr);}}
  function renderFiltered(){visible=filterPapers(data.papers,{query:$('paper-search').value,family:$('family-filter').value});if(!visible.some(p=>p.id===selected)&&!comparators.some(p=>p.id===selected))selected=visible[0]?.id;$('paper-count').textContent=`${visible.length} of ${buehler.length} Buehler papers`;renderSummary();renderList();renderMatrix();renderDetail();}
  $('rank-axis').addEventListener('change',renderFiltered);$('paper-search').addEventListener('input',renderFiltered);$('family-filter').addEventListener('change',renderFiltered);$('reset-filters').addEventListener('click',()=>{$('paper-search').value='';$('family-filter').value='all';renderFiltered();});$('show-comparators').addEventListener('change',()=>{const show=$('show-comparators').checked;$('comparator-papers').hidden=!show;$('comparator-matrix').hidden=!show;if(!show&&comparators.some(p=>p.id===selected)){selected=visible[0]?.id;renderList();renderMatrix();renderDetail();}});
  $('corpus-scope').textContent=data.scope||data.description||'';$('rubric-scale').textContent=data.rubric.scale;$('independence-note').textContent=data.rubric.independence;$('b-date').textContent=data.date||'';for(const a of axes){const detail=el('details');detail.append(el('summary',`${a.kind} / ${a.label}`),el('p',a.question));const list=el('ol');list.start=0;for(const anchor of a.anchors)list.append(el('li',anchor));detail.append(list);$('axis-rubric').append(detail);}for(const rule of data.rubric.protocol||[])$('b-protocol').append(el('li',rule));for(const rule of data.limitations||[])$('b-limitations').append(el('li',rule));renderFeature();renderCorrelation();renderFiltered();status.hidden=true;$('b-content').hidden=false;
}catch(error){status.hidden=false;status.textContent=`The Buehler atlas could not load. ${error.message} Reload to try again.`;status.classList.add('error');const link=el('a','Download profiles JSON');link.href='./papers.json';status.append(link);}}
if(typeof document!=='undefined')boot();
